<div class="page-title"><div><h2>دفترکل <?= e($accountUser['full_name'] ?? '') ?></h2><p class="text-muted">مانده فعلی: <strong><?= money_toman($balance ?? 0) ?></strong></p></div></div>
<section class="card mb-4"><div class="card-header"><h3>ثبت سند حسابداری</h3></div><form method="post" action="<?= e(url('plugin/accounting/ledger/post')) ?>" class="form-grid four"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int) ($accountUser['id'] ?? 0) ?>"><label>نوع سند<select name="entry_type" required><option value="bonus">پاداش</option><option value="expense">هزینه قابل پرداخت</option><option value="deduction">کسری / کسر</option><option value="payment">پرداخت به کاربر</option><option value="receipt">دریافت از کاربر</option></select></label><label>مبلغ<input name="amount" inputmode="numeric" required></label><label class="full">شرح<input name="description" required></label><div class="full"><button class="btn btn-primary" type="submit">ثبت سند</button></div></form></section>
<section class="card"><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>تاریخ</th><th>نوع</th><th>جهت</th><th>مبلغ</th><th>شرح</th><th>عملیات</th></tr></thead><tbody><?php foreach (($entries ?? []) as $entry): ?><tr><td><?= e(jdatetime($entry['created_at'])) ?></td><td><?= e($entry['entry_type']) ?></td><td class="<?= $entry['direction'] === 'credit' ? 'proma-accounting-positive' : 'proma-accounting-negative' ?>"><?= $entry['direction'] === 'credit' ? 'بستانکار' : 'بدهکار' ?></td><td><?= money_toman($entry['amount']) ?></td><td><?= e($entry['description']) ?></td><td><?php if (($entry['entry_type'] ?? '') !== 'reversal' && empty($entry['reversal_of_id'])): ?><form method="post" action="<?= e(url('plugin/accounting/ledger/reverse/' . (int) $entry['id'])) ?>" data-accounting-confirm="این سند معکوس شود؟"><?= csrf_field() ?><input type="hidden" name="reason" value="اصلاح سند دفترکل"><button class="btn btn-sm btn-light" type="submit">ثبت معکوس</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (empty($entries)): ?><tr><td colspan="6" class="empty">هنوز سندی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></section>
